"""Central feature registry.

Every feature is declared once, with its mathematics, motivation, references,
requirements (`required_sampling_frequency`, `min_signal_samples`), expected range,
units, computational cost, novelty status and validation status.

Design rules enforced here
--------------------------
* Feature code is **Python written by the project**, never generated by an LLM.
  An LLM may only *select* registered feature ids and choose parameters inside
  the declared bounds (see :meth:`FeatureRegistry.validate_specification`).
* Feature functions receive a :class:`SignalContext` so that expensive shared
  computations (Welch PSD, band powers, filter cascades) are memoised per epoch.
* Any numeric feature is a pure function of one epoch -> it is deterministic and
  independently testable.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Callable, Iterable, Iterator, Literal

import numpy as np
from scipy import signal as sps

from ..config import ProjectConfig

__all__ = [
    "SignalContext",
    "FeatureDefinition",
    "FeatureRegistry",
    "registry",
    "register_feature",
    "NoveltyStatus",
    "ValidationStatus",
]

NoveltyStatus = Literal["established", "literature-derived", "novel-hypothesis"]
ValidationStatus = Literal[
    "unit-tested",
    "synthetic-validated",
    "reproduced-from-literature",
    "unvalidated",
    "rejected",
]

FeatureFunction = Callable[..., float]


@dataclass
class SignalContext:
    """Per-(epoch, configuration) context with memoised shared computations."""

    epoch: np.ndarray
    sfreq: float
    config: ProjectConfig
    stage: str | None = None
    memo: dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        self.epoch = np.asarray(self.epoch, dtype=np.float64).ravel()
        self.sfreq = float(self.sfreq)

    # -- shared computations ------------------------------------------------- #
    @property
    def bands(self) -> dict[str, tuple[float, float]]:
        return self.config.bands

    @property
    def n_samples(self) -> int:
        return int(self.epoch.size)

    def psd(self) -> tuple[np.ndarray, np.ndarray]:
        """Welch PSD (V^2/Hz), memoised per epoch."""
        if "psd" not in self.memo:
            cfg = self.config.features.psd
            nperseg = int(min(self.n_samples, max(8, round(cfg.welch_window_seconds * self.sfreq))))
            noverlap = int(nperseg * cfg.welch_overlap_fraction)
            freqs, psd = sps.welch(
                self.epoch,
                fs=self.sfreq,
                window="hann",
                nperseg=nperseg,
                noverlap=noverlap,
                detrend=cfg.detrend,
                scaling="density",
            )
            self.memo["psd"] = (freqs, psd)
        return self.memo["psd"]

    def band_power(self, band: str | tuple[float, float]) -> float:
        """Integrated PSD over a band in V^2 (memoised)."""
        key = ("band_power", band)
        if key not in self.memo:
            low, high = self.bands[band] if isinstance(band, str) else band
            freqs, psd = self.psd()
            mask = (freqs >= low) & (freqs < high)
            if not np.any(mask) or np.sum(psd[mask]) == 0:
                value = 0.0
            else:
                value = float(np.trapezoid(psd[mask], freqs[mask]))
            self.memo[key] = value
        return float(self.memo[key])

    def total_power(self) -> float:
        if "total_power" not in self.memo:
            freqs, psd = self.psd()
            low = min(b[0] for b in self.bands.values())
            high = max(b[1] for b in self.bands.values())
            mask = (freqs >= low) & (freqs < high)
            self.memo["total_power"] = float(np.trapezoid(psd[mask], freqs[mask])) if np.any(mask) else 0.0
        return float(self.memo["total_power"])

    def band_limited(self, low: float, high: float, order: int = 4) -> np.ndarray:
        """Zero-phase band-limited copy of the epoch (memoised)."""
        key = ("band_limited", float(low), float(high), int(order))
        if key not in self.memo:
            nyquist = self.sfreq / 2.0
            low_c = max(low, 1e-3)
            high_c = min(high, nyquist * 0.98)
            if high_c <= low_c:
                self.memo[key] = np.zeros_like(self.epoch)
            else:
                sos = sps.butter(order, [low_c / nyquist, high_c / nyquist], btype="bandpass", output="sos")
                padlen = min(3 * (sos.shape[0] * 2), max(0, self.epoch.size - 1))
                if self.n_samples > 12:
                    self.memo[key] = sps.sosfiltfilt(sos, self.epoch, padlen=padlen)
                else:  # pragma: no cover - extremely short epochs
                    self.memo[key] = sps.sosfilt(sos, self.epoch)
        return np.asarray(self.memo[key], dtype=np.float64)

    def lowpass(self, cutoff: float, order: int = 4) -> np.ndarray:
        key = ("lowpass", float(cutoff), int(order))
        if key not in self.memo:
            nyquist = self.sfreq / 2.0
            cutoff = min(cutoff, nyquist * 0.98)
            sos = sps.butter(order, cutoff / nyquist, btype="lowpass", output="sos")
            padlen = min(3 * (sos.shape[0] * 2), max(0, self.epoch.size - 1))
            self.memo[key] = sps.sosfiltfilt(sos, self.epoch, padlen=padlen) if self.n_samples > 12 else self.epoch
        return np.asarray(self.memo[key], dtype=np.float64)


@dataclass(frozen=True)
class FeatureDefinition:
    """Declarative description of one feature."""

    feature_id: str
    name: str
    category: str
    family: str
    function: FeatureFunction
    mathematical_definition: str
    biological_motivation: str = ""
    literature_references: tuple[str, ...] = ()
    parameters: dict[str, Any] = field(default_factory=dict)
    required_sampling_frequency: float = 0.0
    max_required_sampling_frequency: float | None = None
    min_signal_samples: int = 0
    expected_range: tuple[float | None, float | None] = (None, None)
    output_units: str = "dimensionless"
    computational_cost: Literal["low", "medium", "high"] = "low"
    novelty_status: NoveltyStatus = "established"
    validation_status: ValidationStatus = "unit-tested"
    notes: str = ""

    def describe(self) -> dict[str, Any]:
        return {
            "feature_id": self.feature_id,
            "name": self.name,
            "category": self.category,
            "family": self.family,
            "mathematical_definition": self.mathematical_definition,
            "biological_motivation": self.biological_motivation,
            "literature_references": list(self.literature_references),
            "parameters": dict(self.parameters),
            "required_sampling_frequency": self.required_sampling_frequency,
            "max_required_sampling_frequency": self.max_required_sampling_frequency,
            "min_signal_samples": self.min_signal_samples,
            "expected_range": list(self.expected_range),
            "output_units": self.output_units,
            "computational_cost": self.computational_cost,
            "novelty_status": self.novelty_status,
            "validation_status": self.validation_status,
            "notes": self.notes,
        }


class FeatureRegistry:
    """Registry of available feature implementations."""

    def __init__(self) -> None:
        self._features: dict[str, FeatureDefinition] = {}

    # -- registration ------------------------------------------------------- #
    def register(self, definition: FeatureDefinition) -> FeatureDefinition:
        if definition.feature_id in self._features:
            raise ValueError(f"duplicate feature id: {definition.feature_id}")
        self._features[definition.feature_id] = definition
        return definition

    def __contains__(self, feature_id: str) -> bool:
        return feature_id in self._features

    def __len__(self) -> int:
        return len(self._features)

    def __iter__(self) -> Iterator[FeatureDefinition]:
        return iter(self._features.values())

    def get(self, feature_id: str) -> FeatureDefinition:
        try:
            return self._features[feature_id]
        except KeyError as exc:
            raise KeyError(f"unknown feature id: {feature_id}") from exc

    def ids(self) -> list[str]:
        return sorted(self._features)

    def by_family(self, family: str) -> list[FeatureDefinition]:
        return [f for f in self._features.values() if f.family == family]

    def families(self) -> list[str]:
        return sorted({f.family for f in self._features.values()})

    def categories(self) -> list[str]:
        return sorted({f.category for f in self._features.values()})

    def subset(self, feature_ids: Iterable[str]) -> "FeatureRegistry":
        new = FeatureRegistry()
        for feature_id in feature_ids:
            new.register(self.get(feature_id))
        return new

    # -- specification validation (LLM boundary) ---------------------------- #
    def validate_specification(self, specification: dict[str, Any], sfreq: float) -> dict[str, Any]:
        """Validate a (possibly LLM-generated) feature request against the registry.

        Returns ``{"approved": [...], "rejected": [...]}``.  Only registered
        feature ids with in-range parameters and satisfiable signal requirements
        are approved; nothing outside the registry can ever be executed.
        """
        approved: list[dict[str, Any]] = []
        rejected: list[dict[str, Any]] = []
        for item in specification.get("features", specification if isinstance(specification, list) else []):
            feature_id = item.get("feature_id") if isinstance(item, dict) else str(item)
            params = dict(item.get("parameters", {})) if isinstance(item, dict) else {}
            if feature_id not in self._features:
                rejected.append({"feature_id": feature_id, "reason": "not_in_registry"})
                continue
            definition = self._features[feature_id]
            if definition.required_sampling_frequency and sfreq < definition.required_sampling_frequency:
                rejected.append(
                    {
                        "feature_id": feature_id,
                        "reason": f"requires sfreq >= {definition.required_sampling_frequency} Hz (got {sfreq:g})",
                    }
                )
                continue
            if definition.max_required_sampling_frequency and sfreq > definition.max_required_sampling_frequency:
                rejected.append(
                    {
                        "feature_id": feature_id,
                        "reason": (
                            f"requires sfreq <= {definition.max_required_sampling_frequency} Hz "
                            f"(got {sfreq:g})"
                        ),
                    }
                )
                continue
            unknown = set(params) - set(definition.parameters)
            if unknown:
                rejected.append({"feature_id": feature_id, "reason": f"unknown parameters: {sorted(unknown)}"})
                continue
            merged = {**definition.parameters, **params}
            approved.append({"feature_id": feature_id, "parameters": merged})
        return {"approved": approved, "rejected": rejected}

    # -- evaluation --------------------------------------------------------- #
    def compute(
        self,
        context: SignalContext,
        feature_ids: Iterable[str] | None = None,
        *,
        keep_errors: bool = True,
    ) -> tuple[dict[str, float], dict[str, str]]:
        """Compute features for one epoch.

        Returns ``(values, errors)``; failures are reported (never swallowed) so
        the extraction table can record exactly which computations were skipped.
        """
        selected = list(feature_ids) if feature_ids is not None else self.ids()
        values: dict[str, float] = {}
        errors: dict[str, str] = {}
        for feature_id in selected:
            definition = self.get(feature_id)
            if context.n_samples < definition.min_signal_samples:
                errors[feature_id] = (
                    f"insufficient_samples: {context.n_samples} < {definition.min_signal_samples}"
                )
                continue
            try:
                value = definition.function(context, **definition.parameters)
            except Exception as exc:  # noqa: BLE001 - one bad feature must not abort extraction
                errors[feature_id] = f"{type(exc).__name__}: {exc}"
                if not keep_errors:
                    raise
                continue
            values[feature_id] = float(value) if not isinstance(value, np.generic) else float(value.item())
        return values, errors


#: Process-wide registry populated by ``load_default_registry``.
registry = FeatureRegistry()


def register_feature(
    function: FeatureFunction | None = None, **kwargs: Any
) -> FeatureFunction | Callable[[FeatureFunction], FeatureFunction]:
    """Register a feature implementation in the default registry.

    Usable both ways::

        register_feature(function=my_impl, feature_id="x", ...)   # direct

        @register_feature(feature_id="x", ...)                    # decorator
        def my_impl(context, ...): ...
    """
    if function is not None:
        registry.register(FeatureDefinition(function=function, **kwargs))
        return function

    def decorator(impl: FeatureFunction) -> FeatureFunction:
        registry.register(FeatureDefinition(function=impl, **kwargs))
        return impl

    return decorator


def load_default_registry(force: bool = False) -> FeatureRegistry:
    """Import all feature modules so their decorators run, then return the registry."""
    from . import nonlinear, novel_features, sleep_events, spectral, temporal, wavelets  # noqa: F401

    _ = force
    return registry
